{
  "overview": {
    "summary": "A balanced half-day journey from Ubud into Bali’s rural heartland, combining terraced rice landscapes with an introduction to everyday local food traditions.",
    "quickFacts": {
      "scope": "Half day",
      "bestSeason": "Choose a period with weather suitable for walking; terrace paths may become damp after rain.",
      "pace": "Balanced",
      "themes": [
        "Culture",
        "Food"
      ]
    },
    "routeSummary": "Travel north from Ubud through village scenery to the rice terraces, then return toward Ubud for a relaxed meal featuring regional flavors.",
    "highlights": [
      {
        "icon": "🌾",
        "title": "Terraced rice landscapes",
        "note": "Walk uneven terrace paths and observe how irrigation traditions shape the farming landscape."
      },
      {
        "icon": "🍚",
        "title": "Everyday Balinese flavors",
        "note": "Enjoy a relaxed local meal with regional ingredients such as rice, vegetables, sambal, and slow-cooked meats."
      },
      {
        "icon": "🚗",
        "title": "Village scenery beyond Ubud",
        "note": "Connect the countryside and cultural landscape through a quiet rural transfer."
      }
    ]
  },
  "practical": {
    "included": [
      "A half-day route linking Ubud with nearby rural landscapes",
      "Guidance for terrace walking and local food exploration"
    ],
    "notIncluded": [
      "Meals and personal purchases",
      "Personal travel insurance",
      "Any services or transport not arranged independently"
    ],
    "whatToBring": [
      "Comfortable shoes with good grip",
      "Water",
      "Sun protection",
      "Light, breathable clothing",
      "A small amount of modest clothing for respectful visits to local communities"
    ],
    "localTips": [
      {
        "topic": "Walking",
        "note": "Take care on narrow, uneven, or damp paths and allow space for farmers and other walkers."
      },
      {
        "topic": "Food",
        "note": "Ask about ingredients and spice levels if you have allergies or prefer milder dishes."
      },
      {
        "topic": "Respect",
        "note": "Avoid stepping into cultivated areas, and follow local guidance around irrigation channels and farming activity."
      }
    ],
    "healthSafety": "Carry water, use sun protection, and pace yourself in heat or humidity. Seek local medical advice if you feel unwell, and take extra care on wet or uneven ground.",
    "emergencyContacts": []
  },
  "closing": {
    "closingNote": "This compact route offers a grounded view of Bali through its working landscapes, village roads, and food traditions, with time to experience the surroundings at an unhurried pace.",
    "disclaimer": "Travel conditions, road access, weather, walking surfaces, and local practices may change. Confirm current arrangements locally and follow guidance from your driver or host."
  }
}

