function renderHero(itinerary) {
  const hero = itinerary.hero || {};
  const style = hero.photoUrl ? ` style="--hero-image:url('${esc(hero.photoUrl).replace(/'/g, '%27')}')"` : '';
  const location = [itinerary.destination, itinerary.region, itinerary.country].filter(Boolean).map(esc).join(' Â· ');
  return `<header class="hero${hero.photoUrl ? ' has-photo' : ''}"${style}><div class="hero-top"><span class="agency">${esc(itinerary.agencyName || 'Travel Studio')}</span><span class="scope">${esc(itinerary.scopeLabel || itinerary.itineraryMode || '')}</span></div><div class="hero-copy"><p class="hero-kicker">Curated route Â· ${esc(itinerary.paceLevel || 'Balanced')}</p><h1>${esc(itinerary.tripTitle || itinerary.destination || 'Your itinerary')}</h1><p class="hero-location">${location}</p></div></header>`;
}
function facts(itinerary) {
  const quick = itinerary.overview?.quickFacts || {};
  const themes = Array.isArray(quick.themes) ? quick.themes.join(', ') : (quick.themes || (itinerary.themes || []).join(', '));
  const values = [['Duration', quick.scope || itinerary.scopeLabel], ['Pace', quick.pace || itinerary.paceLevel], ['Best for', quick.bestSeason], ['Themes', themes]].filter(([, value]) => value);
  return values.length ? `<div class="facts-strip">${values.map(([label, value]) => `<div class="fact"><span class="fact-label">${esc(label)}</span><strong class="fact-value">${esc(value)}</strong></div>`).join('')}</div>` : '';
}
function renderOverview(itinerary) {
  const overview = itinerary.overview || {};
  const route = Array.isArray(overview.routeSummary) ? overview.routeSummary.filter(Boolean) : [];
  const highlights = Array.isArray(overview.highlights) ? overview.highlights.filter(Boolean) : [];
  if (!overview.summary && !route.length && !highlights.length) return '';
  return `<section class="section overview" id="overview"><h2 class="section-heading">Trip overview</h2>${overview.summary ? `<p class="summary">${esc(overview.summary)}</p>` : ''}${route.length ? `<div class="route-line"><strong>Route</strong>${route.map((stop) => `<span class="route-stop">${esc(stop)}</span>`).join('')}</div>` : ''}${highlights.length ? `<div class="highlights">${highlights.map((highlight) => `<div class="highlight">${icon(highlight.icon || 'sightseeing')}<div><strong>${esc(highlight.title || '')}</strong><span>${esc(highlight.note || '')}</span></div></div>`).join('')}</div>` : ''}</section>`;
}
function blockLabel(block, index) {
  return block.dayLabel || block.day || `Day ${index + 1}`;
}
function renderTravel(activity) {
  const label = [activity.duration, activity.description || activity.title].filter(Boolean).map(esc).join(' Â· ');
  return `<div class="travel-connector"><span></span><span class="travel-line"></span><div class="travel-note">${icon('transport')} ${label || 'Travel to the next stop'}</div></div>`;
}
function renderStop(activity, fallbackTime='') {
  const type = activity.type || 'activity';
  const isStay = type === 'accommodation';
  const title = activity.title || activity.name || (isStay ? 'Accommodation' : 'Planned stop');
  const time = activity.time || fallbackTime;
  const metadata = [activity.area, activity.category].filter(Boolean);
  return `<article class="timeline-stop${isStay ? ' is-accommodation' : ''}"><time class="stop-time">${esc(time)}</time><div class="stop-marker">${icon(type)}</div><div class="stop-content"><div class="stop-topline"><h4>${esc(title)}</h4>${activity.duration ? `<span class="stop-duration">${esc(activity.duration)}</span>` : ''}</div>${activity.description ? `<p class="stop-description">${esc(activity.description)}</p>` : ''}${metadata.length ? `<div class="stop-meta">${metadata.map((value) => `<span>${esc(value)}</span>`).join('')}</div>` : ''}${activity.tip ? `<div class="tip-callout"><span>âœ¦</span><div><b>Local tip</b> Â· ${esc(activity.tip)}</div></div>` : ''}</div></article>`;
}
function accommodationStop(block) {
  const accommodation = block.accommodation;
  if (!accommodation) return '';
  if (typeof accommodation === 'string') return renderStop({ type:'accommodation', title:'Overnight stay', description:accommodation });
  if (Array.isArray(accommodation)) return accommodation.filter(Boolean).map((entry) => renderStop({ type:'accommodation', title:'Overnight stay', description:typeof entry === 'string' ? entry : entry.description, area:typeof entry === 'object' ? entry.area : undefined })).join('');
  return renderStop({ type:'accommodation', title:accommodation.name || 'Overnight stay', description:accommodation.description, area:accommodation.area, tip:accommodation.tip });
}
function renderScheduled(itinerary) {
  const blocks = Array.isArray(itinerary.schedule) ? itinerary.schedule : [];
  const multiDay = itinerary.itineraryMode === 'multi_day';
  const tripDays = Number(itinerary.durationDays) || blocks.length;
  const scale = multiDay ? (tripDays >= 8 ? 'long' : tripDays >= 5 ? 'week' : 'short') : itinerary.itineraryMode === 'half_day' ? 'half' : 'full';
  const index = multiDay ? `<nav class="day-index" aria-label="Itinerary days">${blocks.map((block, i) => `<span>${esc(blockLabel(block, i))}</span>`).join('')}</nav>` : '';
  const body = blocks.map((block, index) => {
    const activities = Array.isArray(block.activities) ? block.activities : [];
    const header = multiDay ? `<header class="day-header day-header-${scale}"><div class="day-number">${String(index + 1).padStart(2, '0')}</div><div><h3>${esc(blockLabel(block, index))}</h3>${block.area || block.summary || block.date ? `<p>${[block.area, block.date, block.summary].filter(Boolean).map(esc).join(' Â· ')}</p>` : ''}</div></header>` : '';
    const stops = activities.map((activity) => activity?.type === 'transport' && !activity.time ? renderTravel(activity) : renderStop(activity || {})).join('') + (multiDay ? accommodationStop(block) : '');
    return `<section class="day-section">${header}<div class="timeline">${stops}</div></section>`;
  }).join('');
  return `<section class="section schedule schedule-${scale}" id="schedule"><h2 class="section-heading">${multiDay ? (scale === 'week' ? 'Your week at a glance' : scale === 'long' ? 'Your extended journey' : 'Your journey') : scale === 'half' ? 'Your half-day agenda' : 'Your day route'}</h2>${index}${body}</section>`;
}
function renderGuide(itinerary) {
  const spots = Array.isArray(itinerary.spots) ? itinerary.spots : [];
  const groups = [];
  spots.forEach((spot) => { const label = spot.groupLabel || ''; let group = groups.find((entry) => entry.label === label); if (!group) { group = { label, spots: [] }; groups.push(group); } group.spots.push(spot); });
  const groupMarkup = groups.map((group, groupIndex) => `<section class="guide-group">${group.label ? `<div class="guide-group-heading"><span class="group-number">AREA ${String(groupIndex + 1).padStart(2, '0')}</span><h3>${esc(group.label)}</h3></div><p>Explore these places as one area, with enough room to follow your own pace.</p>` : ''}<div class="spot-grid">${group.spots.map((spot, spotIndex) => `<article class="spot-card"><span class="spot-index">PLACE ${String(spotIndex + 1).padStart(2, '0')}</span><h4>${esc(spot.name || '')}</h4><p class="spot-subtitle">${[spot.area, spot.category].filter(Boolean).map(esc).join(' Â· ')}</p>${spot.description ? `<p class="spot-description">${esc(spot.description)}</p>` : ''}<dl class="spot-details"><div><dt>Suggested visit</dt><dd>${esc(spot.suggestedDuration || '')}</dd></div><div><dt>Best time</dt><dd>${esc(spot.bestTimeToVisit || '')}</dd></div><div><dt>Getting there</dt><dd>${esc(spot.gettingThere || '')}</dd></div>${spot.nearbyPairing ? `<div><dt>Pairs well with</dt><dd>${esc(spot.nearbyPairing)}</dd></div>` : ''}</dl>${textList(spot.tips).length ? `<p class="spot-tip"><b>Local tip</b> Â· ${textList(spot.tips)[0]}</p>` : ''}</article>`).join('')}</div></section>`).join('');
  return `<section class="section guide" id="guide"><h2 class="section-heading">Explore the destination</h2><p class="guide-intro">Choose the places that fit your interests and build each area at your own pace.</p><div class="guide-groups">${groupMarkup}</div></section>`;
}
function renderPractical(itinerary) {
  const practical = itinerary.practical || {};
  const groups = [['What to bring', practical.whatToBring], ['Included', practical.included], ['Not included', practical.notIncluded], ['Local notes', practical.localTips], ['Health & safety', practical.healthSafety], ['Emergency contacts', practical.emergencyContacts]].filter(([, values]) => Array.isArray(values) && values.length);
  if (!groups.length) return '';
  return `<section class="section practical" id="practical"><h2 class="section-heading">Know before you go</h2><div class="practical-grid">${groups.map(([title, values]) => { const items = textList(values); return `<div class="practical-item"><h3>${esc(title)}<span>${items.length} item${items.length === 1 ? '' : 's'}</span></h3><ul>${items.map((item) => `<li>${item}</li>`).join('')}</ul></div>`; }).join('')}</div></section>`;
}
function renderClosing(itinerary) {
  const closing = itinerary.closing || {};
  const credits = Array.isArray(closing.photoCredits) ? closing.photoCredits.filter(Boolean) : [];
  if (!closing.closingNote && !closing.agencyContact && !closing.disclaimer && !credits.length) return '';
  return `<footer class="closing"><h2>Travel with confidence.</h2>${closing.closingNote ? `<p>${esc(closing.closingNote)}</p>` : ''}${closing.agencyContact ? `<p><strong>${esc(closing.agencyContact)}</strong></p>` : ''}${closing.disclaimer ? `<p>${esc(closing.disclaimer)}</p>` : ''}${credits.length ? `<div class="credits">Photo credits: ${credits.map((credit) => esc(credit.photographer || credit.source || '')).join(' Â· ')}</div>` : ''}</footer>`;
}
function renderItineraryHtml(itinerary = {}, options = {}) {
  const visibility = { ...DEFAULT_VISIBILITY, ...(options.visibility || itinerary.sectionVisibility || {}) };
  const mode = itinerary.itineraryMode || 'full_day';
