function renderHero(itinerary) {
  const hero = itinerary.hero || {};
  const style = hero.photoUrl ? ` style="--hero-image:url('${esc(hero.photoUrl).replace(/'/g, '%27')}')"` : '';
  const location = [itinerary.destination, itinerary.region, itinerary.country].filter(Boolean).map(esc).join(' Â· ');
  return `<header class="hero${hero.photoUrl ? ' has-photo' : ''}"${style}><div class="hero-top"><span class="agency">${esc(itinerary.agencyName || 'Travel Studio')}</span><span class="scope">${esc(itinerary.scopeLabel || itinerary.itineraryMode || '')}</span></div><div class="hero-copy"><p class="hero-kicker">Curated route Â· ${esc(itinerary.paceLevel || 'Balanced')}</p><h1>${esc(itinerary.tripTitle || itinerary.destination || 'Your itinerary')}</h1><p class="hero-location">${location}</p></div></header>`;
}
function facts(itinerary) {
  const quick = itinerary.overview?.quickFacts || {};
  const themes = Array.isArray(quick.themes) ? quick.themes.join(', ') : (quick.themes || (itinerary.themes || []).join(', '));
  const values = [['Duration', quick.scope || itinerary.scopeLabel], ['Pace', quick.pace || itinerary.paceLevel], ['Best for', quick.bestSeason], ['Themes', themes]].filter(([, value]) => value);
  return values.length ? `<div class="facts-strip">${values.map(([label, value]) => `<div class="fact"><span class="fact-label">${esc(label)}</span><strong class="fact-value">${esc(value)}</strong></div>`).join('')}</div>` : '';
}
function renderOverview(itinerary) {
  const overview = itinerary.overview || {};
  const route = Array.isArray(overview.routeSummary) ? overview.routeSummary.filter(Boolean) : [];
  const highlights = Array.isArray(overview.highlights) ? overview.highlights.filter(Boolean) : [];
  if (!overview.summary && !route.length && !highlights.length) return '';
  return `<section class="section overview" id="overview"><h2 class="section-heading">Trip overview</h2>${overview.summary ? `<p class="summary">${esc(overview.summary)}</p>` : ''}${route.length ? `<div class="route-line"><strong>Route</strong>${route.map((stop) => `<span class="route-stop">${esc(stop)}</span>`).join('')}</div>` : ''}${highlights.length ? `<div class="highlights">${highlights.map((highlight) => `<div class="highlight">${icon(highlight.icon || 'sightseeing')}<div><strong>${esc(highlight.title || '')}</strong><span>${esc(highlight.note || '')}</span></div></div>`).join('')}</div>` : ''}</section>`;
