function renderStop(activity, fallbackTime='') {
  const type = activity.type || 'activity';
  const isStay = type === 'accommodation';
  const title = activity.title || activity.name || (isStay ? 'Accommodation' : 'Planned stop');
  const time = activity.time || fallbackTime;
  const metadata = [activity.area, activity.category].filter(Boolean);
  return `<article class="timeline-stop${isStay ? ' is-accommodation' : ''}"><time class="stop-time">${esc(time)}</time><div class="stop-marker">${icon(type)}</div><div class="stop-content"><div class="stop-topline"><h4>${esc(title)}</h4>${activity.duration ? `<span class="stop-duration">${esc(activity.duration)}</span>` : ''}</div>${activity.description ? `<p class="stop-description">${esc(activity.description)}</p>` : ''}${metadata.length ? `<div class="stop-meta">${metadata.map((value) => `<span>${esc(value)}</span>`).join('')}</div>` : ''}${activity.tip ? `<div class="tip-callout"><span>âœ¦</span><div><b>Local tip</b> Â· ${esc(activity.tip)}</div></div>` : ''}</div></article>`;
